  cycle_nudge_ovulation_timing_body: "精子最多能存活五天，卵子只有 12 到 24 小时。抓住前几天，而不是只盯某一天——次数比精准更重要。",
  cycle_nudge_luteal_sleep_headline: "这周要守护好你的*睡眠*",
  cycle_nudge_luteal_sleep_body: "孕酮会让体温升高、睡眠变得断断续续。凉爽的房间和更早的睡前放松，对心情的稳定作用超出你的想象。",
  cycle_nudge_luteal_move_headline: "散步胜过*胡思乱想*",
  cycle_nudge_luteal_move_body: "黄体晚期的低落来自激素，并不是对你生活的评判。二十分钟的日光和活动，比刷手机更能让情绪重新转起来。",
  cycle_nudge_fertility_follicular_headline: "你的窗口*快到了*",
  cycle_nudge_fertility_follicular_body: "雌激素正在为排卵积蓄力量。排卵前的五天就是你的受孕窗口——精子能等卵子那么久。",
  cycle_nudge_fertility_luteal_headline: "窗口*已关闭*",
  cycle_nudge_fertility_luteal_body: "卵子只能存活 12–24 小时，所以周期的这一段受孕机会较低。如果你测过或安排过，现在就只剩等待了。",
  cycle_nudge_fertility_menstruation_headline: "*全新*周期开始了",
  cycle_nudge_fertility_menstruation_body: "第一天让时钟重新归零。你的下一个受孕窗口大约在两周后——这是窗口开启前安心休息、做好准备的一段平静时光。",
  cycle_nudge_reflect_mood_headline: "你今天*感觉*怎么样？",
  cycle_nudge_reflect_mood_body: "简单记一下心情，慢慢就能拼出全貌——记录几个周期后，更容易看出各阶段的规律。",
  cycle_nudge_reflect_symptom_headline: "今天有*什么感觉*吗？",
  cycle_nudge_reflect_symptom_body: "痛经、乳房胀痛、头痛？记录症状能帮你和医生看清哪些是你一贯的状态。",
  cycle_nudge_reflect_energy_headline: "你的*精力*怎么样？",
  cycle_nudge_reflect_energy_body: "经期前精力自然会下降。今天记一下，能帮你顺着自己的节奏安排，而不是和它对抗。",
  cycle_nudge_nutrition_luteal_headline: "多吃点*含镁*的食物",
  cycle_nudge_nutrition_luteal_body: "黑巧克力、杏仁、南瓜子和香蕉，能缓解周期后半段的痛经并稳定心情。搭配复合碳水，可以减轻嘴馋。",
  cycle_nudge_nutrition_ovulation_headline: "滋养*卵子*",
  cycle_nudge_nutrition_ovulation_body: "富含抗氧化物的食物——莓果、绿叶菜、坚果——有助于卵子质量。排卵前后，锌（南瓜子、鹰嘴豆）尤其重要。",
  cycle_nudge_edu_menstruation_headline: "经期是*第一天*",
  cycle_nudge_edu_menstruation_body: "周期第一天是真正出血的第一天，而不是点滴出血。所有预测都从这一天算起——所以准确记录会让一切更精准。",
  cycle_nudge_edu_follicular_headline: "只有一个卵泡*胜出*",
  cycle_nudge_edu_follicular_body: "每个周期会有多个卵泡开始生长，但通常只有一个成熟并排出卵子。推动这一选择的是不断上升的雌激素。",
  cycle_nudge_edu_ovulation_headline: "一个*36 小时*的事件",
  cycle_nudge_edu_ovulation_body: "排卵本身很短暂——LH 峰值会在约 24–36 小时内触发排卵。所以排卵试纸是为了抓住峰值，而不是排卵那一刻。",
  cycle_nudge_edu_luteal_headline: "*两周*的等待",
  cycle_nudge_edu_luteal_body: "黄体期相当稳定——不论周期长短，通常都是 12–14 天。周期的大部分变化来自前半段，而不是这一段。",
