  help_catCare: "照护圈",
  help_catAi: "Grandma AI",
  help_catBilling: "订阅与账单",
  help_catPrivacy: "隐私",
  help_q_modes: "什么是旅程模式？",
  help_a_modes: "grandma.app 会根据你所处的阶段调整：周期（记录周期或备孕）、孕期、育儿（0–5 岁）和更年期。每段旅程都会改变你的首页、记录内容和 Grandma 的建议。",
  help_q_switchMode: "怎么切换模式？",
  help_a_switchMode: "打开“设置”标签，在“我的旅程”中点选一段旅程。每段旅程的数据分开保存，切换时不会丢失。",
  help_q_logging: "怎么记录一件事？",
  help_a_logging: "在首页或“日历”标签记录——选好日期和要记的内容：月经、症状、心情、睡眠等。所有记录都会出现在日历和你的笔记里。",
  help_q_export: "怎么导出我的数据？",
  help_a_export: "前往 设置 → 数据与隐私 → 我们持有的数据 → 导出我的所有数据。你会得到一份完整的、机器可读的 JSON 副本，包含我们存储的所有内容。",
  help_q_delete: "怎么删除我的账号？",
  help_a_delete: "设置 → 账号 → 删除账号。这会从我们的系统中永久清除你的数据，且无法恢复。",
  help_q_password: "怎么更改密码？",
  help_a_password: "设置 → 账号 → 更改密码。如果你是用 Apple 或 Google 登录的，请通过对应的服务商管理登录。",
  help_q_invite: "怎么邀请我的照护圈？",
  help_a_invite: "设置 → 照护圈 → 邀请。把安全链接发给伴侣、保姆或祖父母。他们加入后只拥有你选择的权限。",
  help_q_permissions: "我能控制照护者看到什么吗？",
  help_a_permissions: "可以。每位照护者的权限都由你设置，你决定谁可以查看或添加记录、健康档案等。随时可以更改或收回权限。",
  help_q_grandma: "Grandma 是谁？",
  help_a_grandma: "Grandma 是你的 AI 伙伴，由 Claude 提供支持。她会结合你的旅程背景回答问题，日夜都能给你温暖、实用的指引。",
  help_q_medical: "Grandma 的建议是医疗建议吗？",
  help_a_medical: "不是。Grandma 提供的是关怀式的科普指引，不是诊断或治疗。如有医疗方面的疑虑，请务必咨询你的医生、助产士或儿科医生。",
  help_q_premium: "Premium 包含什么？",
  help_a_premium: "Premium 可解锁不限次数的扫描和聊天、完整洞察和提醒。你可以按月或按年订阅。",
  help_q_cancel: "怎么取消 Premium？",
  help_a_cancel: "你可以随时在应用商店的账号设置中管理或取消订阅。Premium 功能会保持到当前计费周期结束。",
  help_q_dataSafe: "我的数据安全吗？",
  help_a_dataSafe: "安全。你的数据在传输和存储时都经过加密，并有行级安全保护，只有你和你选择的照护圈才能访问。",
  help_q_sell: "你们会出售我的数据吗？",
  help_a_sell: "绝不会。我们不出售你的个人数据，也绝不会用你私密的健康或孩子数据来训练第三方 AI。",
