  sw2_leap19_name: "事件",
  sw2_leap19_desc: "理解动作是按顺序发生的",
  sw2_leap19_brain: "这个阶段，宝宝常常开始把世界看作一连串的事件，而不是一团模糊。动作有开始、过程和结束。这是因果思维的起点，也是为什么一切突然显得那么有趣。",
  sw2_leap19_tip: "玩玩躲猫猫这类简单的因果游戏吧——宝宝正在学习事情会有可预期的结果。",
  sw2_leap19_ph0: "特别黏人，放下就哭，睡眠被打乱。新鲜事一下子太多，宝宝可能会觉得累。",
  sw2_leap19_ph1: "宝宝常常忙着把动作和接下来发生的事联系起来——推一推、扔一扔、仔细观察。",
  sw2_leap19_ph2: "开始有意识地伸手够东西，也初步懂得物体依然存在——会去找掉落的东西。",
  sw2_leap19_sg0: "分离焦虑增强",
  sw2_leap19_sg1: "特别黏人",
  sw2_leap19_sg2: "玩具掉了就哭",
  sw2_leap19_sg3: "抗拒小睡",
  sw2_leap19_sg4: "总要人陪着互动",
  sw2_leap19_sg5: "作息被打乱时会烦躁",
  sw2_leap19_sk0: "有意识地伸手抓取",
  sw2_leap19_sk1: "摇晃、敲打玩具",
  sw2_leap19_sk2: "认得熟悉的游戏",
  sw2_leap19_sk3: "懂得“上”和“下”",
  sw2_leap19_sk4: "用眼睛追随移动的物体",
  sw2_leap19_sk5: "被小惊喜逗笑",
  sw2_leap19_ac0: "躲猫猫和捉迷藏游戏",
  sw2_leap19_ac1: "来回滚球",
  sw2_leap19_ac2: "简单的因果玩具（按一下发出声音）",
  sw2_leap19_ac3: "把日常步骤一步步说出来",
  sw2_leap5_name: "感官的变化",
  sw2_leap5_desc: "宝宝发现了更丰富的感官世界",
  sw2_leap5_brain: "这个阶段，宝宝可能开始通过感官接收到更多细节：更清晰的画面、更丰富的声音、新的身体感觉。这既可能让他们应接不暇，也是很美妙的事。",
  sw2_leap5_ph0: "哭闹增多、更黏人、睡眠不安稳都很常见。宝宝可能正在接收大量新的感官信息。",
  sw2_leap5_ph1: "宝宝正在吸收许多新的画面和声音。烦躁可能先达到高峰，然后慢慢平静。",
  sw2_leap5_ph2: "新的感官意识逐渐绽放，你会发现宝宝清醒的时间更长，也更会有意地注视。",
  sw2_leap5_sg0: "比平时哭得多",
  sw2_leap5_sg1: "总想吃奶",
  sw2_leap5_sg2: "更难安抚",
  sw2_leap5_sg3: "喜欢贴近",
  sw2_leap5_sg4: "更容易受惊",
